import { Component, inject, Injectable, Injector, OnInit, TemplateRef, Type } from '@angular/core';
import { ButtonComponent, ButtonConfig } from 'espd-common/button';
import { MessageConfig, MessageService } from 'espd-common/i18n';
import { ModalOptions as BsModalOptions, BsModalRef, BsModalService } from 'ngx-bootstrap/modal';
import { catchError, filter, finalize, map, Observable, of, Subject, Subscription } from 'rxjs';
import { MODAL_SUCCESS_CONFIG, ModalSuccessComponent } from './modal-success/modal-success.component';

export interface ModalButton<T> extends ButtonConfig {
	value?: T | (() => Observable<T>);
	nextState?: string | (() => Observable<string | undefined>);
}

export interface WorkflowOptions {
	dismissable: boolean;
	class: string;
}

export interface StateOptions {
	bodyPadding: boolean;
	manualButtonPlacement: boolean;
}

export interface ComponentConfig {
	type: Type<any>;
	injector?: Injector;
	module?: Type<any>;
	content?: any[][];
}

export type ModalBody = MessageConfig | string | TemplateRef<any> | ComponentConfig;
export type ModalOptions = WorkflowOptions & StateOptions;

export interface State<T> {
	template?: TemplateRef<any>;
	component?: ComponentConfig;
	body?: string;
	title?: string | MessageConfig;
	buttons?: ModalButton<T>[];
	footerControlTemplate?: TemplateRef<any>;
	options?: Partial<StateOptions>;
}

export interface Workflow<T> {
	onChangeState?: (state: string) => void;
	states: Record<string, State<T>>;
	initialState: string;
	options?: Partial<WorkflowOptions>;
}

export interface ModalInterface {
	setState(stateKey: string): void;
	resolveWith(value: unknown): void;
}

export interface WorkflowRef<T> {
	result: Observable<T>;
	modalRef: BsModalRef<ModalInterface>;
}

@Injectable()
export class ModalService {
	private defaultButtons: ModalButton<any>[] = [];
	private hideSubscription?: Subscription;

	private messageService = inject(MessageService);
	private modalService = inject(BsModalService);

	constructor() {
		this.messageService.waitFor('espd-common').subscribe(() => {
			this.defaultButtons = [
				{ content: this.messageService.get('common.ok'), value: true },
				{ content: this.messageService.get('common.cancel'), value: false, secondary: true }
			];
		});
	}

	public show<T>(title: MessageConfig | string, body: ModalBody, buttons?: ModalButton<T>[], options?: Partial<ModalOptions>): Observable<T | undefined> {
		return this.showRef(title, body, buttons, options).result;
	}

	public showRef<T>(title: MessageConfig | string, body: ModalBody, buttons?: ModalButton<T>[], options?: Partial<ModalOptions>): WorkflowRef<T | undefined> {
		const state: State<T> = {
			buttons: buttons ?? this.defaultButtons,
			options
		};

		this.applyBodyToState(body, state);
		return this.showWorkflowRef(title, { states: { default: state }, initialState: 'default', options });
	}

	public showWorkflow<T>(title: MessageConfig | string, workflow: Workflow<T>): Observable<T | undefined> {
		return this.showWorkflowRef(title, workflow).result;
	}

	public showWorkflowRef<T>(title: MessageConfig | string, workflow: Workflow<T>): WorkflowRef<T | undefined> {
		let config: BsModalOptions = {
			class: workflow.options?.class,
			initialState: {
				title: title,
			}
		};

		const subject = new Subject<T | undefined>();
		const canDismiss = workflow.options?.dismissable ?? false;

		const defaultConfig: BsModalOptions = {
			keyboard: canDismiss,
			ignoreBackdropClick: !canDismiss
		};

		const initialState = { workflow, completionSubject: subject, ...config.initialState };

		config = { ...defaultConfig, ...config };
		config.initialState = initialState;

		this.hideSubscription = this.modalService.onHide.subscribe(() => {
			// Possible values are backdrop-click, esc or null if modal was closed by direct call of hide()
			subject.next(undefined);
			subject.complete();
			this.hideSubscription?.unsubscribe();
		});

		const modalRef = this.modalService.show(ModalContentComponent<T>, config);
		return {
			result: subject.asObservable(),
			modalRef: modalRef
		};
	}

	public showSingleStepWorkflow(title: MessageConfig | string, body: ModalBody, actionButtonConfig: ModalButton<boolean>, action: () => Observable<boolean>, successMessage: MessageConfig | string, options?: Partial<ModalOptions>): Observable<boolean | undefined> {
		title = this.messageService.evaluate(title);

		const cancelButton = { content: this.messageService.get('common.cancel'), value: false, secondary: true };
		const closeButton = { content: this.messageService.get('common.close'), value: true, secondary: true };

		actionButtonConfig.value = undefined;
		actionButtonConfig.nextState = () => action().pipe(
			catchError(() => of(false)),
			map(result => result ? 'success' : 'first')
		);

		const firstState: State<boolean> = {
			buttons: [actionButtonConfig, cancelButton],
			options
		};

		this.applyBodyToState(body, firstState);

		const defaultOptions = {
			dismissable: true
		}
		options = { ...defaultOptions, ...options };

		const workflow = {
			states: {
				first: firstState,
				success: {
					component: {
						type: ModalSuccessComponent,
						injector: Injector.create({
							providers: [{ provide: MODAL_SUCCESS_CONFIG, useValue: successMessage }]
						})
					},
					buttons: [closeButton]
				}
			},
			initialState: 'first',
			options
		};

		return this.showWorkflow(title, workflow);
	}

	private applyBodyToState(body: ModalBody, state: State<any>) {
		function instanceOfMessageConfig(object: any): object is MessageConfig {
			return 'key' in object;
		}

		if (typeof body === 'string' || instanceOfMessageConfig(body)) {
			state.body = this.messageService.evaluate(body);
		} else if (body instanceof TemplateRef) {
			state.template = body;
		} else {
			state.component = body;
		}
	}
}

@Component({
	// eslint-disable-next-line @angular-eslint/component-selector
	selector: 'modal-content',
	template: `
	@if (resolvedTitle) {
		<div class="modal-header text-break">
			<h2 class="modal-title">{{resolvedTitle}}</h2>
			@if (canDismiss) {
				<espd-button
					color="close"
					[title]="messageService.get('common.close')"
					[attr.aria-label]="messageService.get('common.close')"
					(click)="bsModalRef.hide()" />
			}
		</div>
	}

	<ng-template #buttons>
		@if (state && ((!!state.buttons && state.buttons.length > 0) || state.footerControlTemplate)) {
			<div class="modal-footer justify-content-between text-break">
				<div>
					@if (state.footerControlTemplate) {
						<ng-container *ngTemplateOutlet="state.footerControlTemplate; context: {bsModalRef : bsModalRef}" />
					}
				</div>
				<div>
					@for (button of state.buttons; track $index) {
						<espd-button #buttonCmp
							[config]="button"
							(click)="clickButton(button, buttonCmp)" />
					}
				</div>
			</div>
		}
	</ng-template>

	@if (state) {
		<div class="modal-body text-break" [class.p-0]="removeBodyPadding">
			@if (state.body) {
				<div [innerHTML]="state.body"></div>
			}
			@if (state.template) {
				<ng-container *ngTemplateOutlet="state.template; context: {bsModalRef : bsModalRef, buttonTemplateRef: buttons}" />
			}
			@if (state.component) {
				<ng-container *ngComponentOutlet="state.component.type; injector: state.component.injector; content: state.component.content; ngModule: state.component.module;" />
			}
		</div>
		@if (showButtons) {
			<ng-container *ngTemplateOutlet="buttons" />
		}
	}
	`,

	standalone: false
})
export class ModalContentComponent<T> implements ModalInterface, OnInit {
	public title = '';
	public workflow?: Workflow<T>;
	public completionSubject?: Subject<T>;

	private _state?: State<T>;
	public get state(): State<T> | undefined {
		return this._state;
	}
	public set state(newState: State<T> | undefined) {
		this._state = newState;
	}

	public bsModalRef = inject(BsModalRef);
	public messageService = inject(MessageService);

	ngOnInit(): void {
		this.state = this.workflow?.states[this.workflow.initialState];
	}

	get resolvedTitle(): string {
		return this.messageService.evaluate(this.state?.title ?? this.title);
	}

	get removeBodyPadding(): boolean {
		return !(this.state?.options?.bodyPadding ?? true);
	}

	get showButtons(): boolean {
		return !(this.state?.options?.manualButtonPlacement ?? false);
	}

	get canDismiss(): boolean {
		return this.workflow?.options?.dismissable ?? false;
	}

	public setState(stateKey: string): void {
		if (this.state !== this.workflow?.states[stateKey]) {
			if (this.workflow?.onChangeState) this.workflow.onChangeState(stateKey);
			this.state = this.workflow?.states[stateKey];
		}
	}

	public resolveWith(value: T): void {
		this.bsModalRef.hide();
		if (this.completionSubject) {
			this.completionSubject.next(value);
			this.completionSubject.complete();
		}
	}

	public clickButton(button: ModalButton<T>, buttonCmp: ButtonComponent): void {
		if (button.nextState) {
			this.goToNextState(button, buttonCmp);
		} else if (button.value !== undefined) {
			this.returnValue(button.value, buttonCmp);
		}
	}

	private goToNextState(button: ModalButton<T>, buttonCmp: ButtonComponent) {
		let nextState: Observable<string | undefined>;
		if (typeof button.nextState === 'string') {
			nextState = of(button.nextState);
		} else {
			nextState = button.nextState!();
		}
		buttonCmp.loading.set(true);
		nextState
			.pipe(
				finalize(() => buttonCmp.loading.set(false)),
				filter((state): state is string => !!state))
			.subscribe(state => this.setState(state));
	}

	private returnValue(buttonValue: T | (() => Observable<T>), buttonCmp: ButtonComponent): void {
		const finalValue: Observable<T> = buttonValue instanceof Function
			? buttonValue()
			: of(buttonValue);

		buttonCmp.loading.set(true);
		finalValue
			.pipe(finalize(() => buttonCmp.loading.set(false)))
			.subscribe((value: T) => this.resolveWith(value));
	}
}