import { ModuleWithProviders, NgModule } from '@angular/core';
import { CommonModule } from '@angular/common';
import { ButtonModule } from 'espd-common/button';
import { ModalContentComponent, ModalService } from './modal.service';

@NgModule({
	imports: [
		CommonModule,
		ButtonModule
	],
	declarations: [
		ModalContentComponent
	]
})
export class ModalModule {
	public static forRoot(): ModuleWithProviders<ModalModule> {
		return { ngModule: ModalModule, providers: [ModalService] };
	}
}
