import { Component, inject, TemplateRef, ViewChild } from '@angular/core';
import { MessageConfig, MessageService } from 'espd-common/i18n';
import { map, Observable } from 'rxjs';
import { ModalSuccessComponent } from '../modal-success/modal-success.component';
import { ModalService } from '../modal.service';

/**
 * @deprecated Use showSingleStepWorkflow() in ModalService instead
 */
@Component({
	selector: 'espd-single-step-modal',
	imports: [ModalSuccessComponent],
	templateUrl: './single-step-modal.component.html',
	styleUrls: ['./single-step-modal.component.scss']
})
export class SingleStepModalComponent {

	public successMessage!: string;

	@ViewChild('successModalTemplate')
	public successModalTemplate!: TemplateRef<any>;

	public messageService = inject(MessageService);
	private modalService = inject(ModalService);

	public show(title: MessageConfig | string, body: MessageConfig | string | TemplateRef<any> | undefined, actionButtonText: string, action: () => Observable<boolean>, successMessage: MessageConfig | string): Observable<boolean | undefined> {
		this.successMessage = this.messageService.evaluate(successMessage);

		if (!(body instanceof TemplateRef)) {
			body = body ? this.messageService.evaluate(body) : undefined;
		}

		title = this.messageService.evaluate(title);

		const cancelButton = {
			content: this.messageService.get('common.cancel'),
			value: false,
			secondary: true
		};
		const closeButton = { content: this.messageService.get('common.close'), value: true };

		const workflow = {
			states: {
				first: {
					template: body instanceof TemplateRef ? body : undefined,
					body: body instanceof TemplateRef ? undefined : body,
					buttons: [
						{
							content: actionButtonText,
							nextState: () => action().pipe(map(result => result ? 'success' : 'first'))
						},
						cancelButton
					]
				},
				success: {
					template: this.successModalTemplate,
					buttons: [closeButton]
				}
			},
			initialState: 'first',
			options: {
				dismissable: true
			}
		};

		return this.modalService.showWorkflow(title, workflow);
	}
}