import { Component, InjectionToken, Input, OnInit, inject } from '@angular/core';
import { MessageConfig, MessageModule } from 'espd-common/i18n';
import { IconDirective } from 'espd-common/icon';

export const MODAL_SUCCESS_CONFIG = new InjectionToken<MessageConfig | string>('modal-success.config');

@Component({
	selector: 'espd-modal-success',
	imports: [IconDirective, MessageModule],
	templateUrl: './modal-success.component.html',
	styleUrls: ['./modal-success.component.scss']
})
export class ModalSuccessComponent implements OnInit {

	private injectedConfig = inject(MODAL_SUCCESS_CONFIG, { optional: true });

	@Input()
	public config?: MessageConfig | string;

	public ngOnInit(): void {
		this.config = (this.config ?? this.injectedConfig) ?? undefined;
	}
}